// function calculateDiscount(amount, isMember, isNew)
// Member aur new: 30% off
// Sirf member: 20% off
// Sirf new: 10% off
// Dono nahi: 0% off

solution:
function calculateDiscount(amount, isMember, isNew) {
  if (isMember && isNew) return amount * 0.7
  else if (isMember) return amount * 0.8
  else if (isNew) return amount * 0.9
  else return amount
}
